def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    # Each slot stores count in s minus count in t.
    balance = [0] * 26
    base = ord('a')
    for i in range(len(s)):
        balance[ord(s[i]) - base] += 1
        balance[ord(t[i]) - base] -= 1
    return all(count == 0 for count in balance)

solution.java:
class Solution {
    public boolean isAnagram(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }
        // Each slot stores count in s minus count in t.
        int[] balance = new int[26];
        for (int i = 0; i < s.length(); i++) {
            balance[s.charAt(i) - 'a']++;
            balance[t.charAt(i) - 'a']--;
        }
        for (int count : balance) {
            if (count != 0) return false;
        }
        return true;
    }
}

solution.javascript:
function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    // Each slot stores count in s minus count in t.
    const balance = new Array(26).fill(0);
    const base = 'a'.charCodeAt(0);
    for (let i = 0; i < s.length; i++) {
        balance[s.charCodeAt(i) - base]++;
        balance[t.charCodeAt(i) - base]--;
    }
    return balance.every(count => count === 0);
}
